// Ningún mensaje real sale hacia el set de datos: solo a los correos de la tabla destinos_prueba.
// Lo demás (por ejemplo, los correos @solarandes.test del equipo) se desvía al correo de prueba.
// Cada correo trae { para, quien, asunto, texto } y, si quien llama lo necesita, una referencia (ref)
const filas = $('Leer destinos').all().map((i) => i.json);
const correos = filas.filter((f) => f.tipo === 'correo' && f.valor).map((f) => String(f.valor).trim().toLowerCase());
const remitente = filas.find((f) => f.tipo === 'remitente' && f.valor)?.valor;
if (!correos.length || !remitente) throw new Error('Destino seguro: faltan las filas correo y remitente en destinos_prueba');

return $('Cuando lo llamen').all().map(({ json: c }) => {
  const para = String(c.para ?? '').trim().toLowerCase();
  const permitido = correos.includes(para);
  return {
    json: {
      ref: c.ref ?? null,
      remitente,
      para: permitido ? para : correos[0],
      asunto: permitido ? c.asunto : `[Prueba: era para ${c.quien} <${para}>] ${c.asunto}`,
      texto: c.texto,
      desviado: !permitido,
    },
  };
});

// Qué pasó con cada correo, en el mismo orden en que llegaron. Un correo que falla no detiene a los
// demás: quien llamó decide (01c falla y avisa; 03 suelta ese resumen para la hora siguiente).
// "Salió" se comprueba en positivo (Gmail lo aceptó): si el paso de correo falla entero (por ejemplo,
// sin credencial), n8n deja pasar los correos tal como entraron, sin error y sin haberlos enviado
return $input.all().map((item, i) => {
  const enviado = $('Destino seguro').itemMatching(i).json;
  const r = item.json;
  const ok = Array.isArray(r.accepted) && r.accepted.length > 0 && !(r.rejected?.length);
  const error = ok ? null : (r.error?.message ?? r.error ?? 'Gmail no confirmó que aceptara el correo');
  return { json: { ref: enviado.ref, desviado: enviado.desviado, ok, error } };
});
